  logic w_apb_prot_ok;
  logic w_apb_slverr;
  logic w_apb_complete;
  logic w_apb_wr;
  logic w_apb_rd;
  logic [LPARA_ADDR_W-1:0] reg_addr;
  logic [LPARA_DATA_W-1:0] reg_wdata;
  logic [LPARA_STRB_W-1:0] reg_wstrb;
  logic [LPARA_DATA_W-1:0] w_wmask;
  logic reg_slverr;
  logic w_rd_en;
  logic w_wr_en;
  logic w_rd_ack_fall;
  logic [LPARA_DATA_W-1:0] w_rdata_nxt;
  logic [LPARA_DATA_W-1:0] reg_rdata;
  logic w_clk_reg;
  logic w_rst_n_reg;
  logic [LPARA_DATA_W-1:0] w_cha_version_value;
  logic w_we_cha_ctrl;
  logic [3:0] reg_cha_ctrl_key_slot;
  logic [3:0] w_cha_ctrl_key_slot_nxt;
  logic reg_cha_ctrl_tail_mode;
  logic w_cha_ctrl_tail_mode_nxt;
  logic reg_cha_ctrl_dma_en;
  logic w_cha_ctrl_dma_en_nxt;
  logic reg_cha_ctrl_abort;
  logic w_cha_ctrl_abort_nxt;
  logic reg_cha_ctrl_dir;
  logic w_cha_ctrl_dir_nxt;
