  logic w_cha_ctrl_start_nxt;
  logic reg_cha_ctrl_en;
  logic w_cha_ctrl_en_nxt;
  logic [LPARA_DATA_W-1:0] w_cha_ctrl_value;
  logic w_we_cha_len;
  logic [15:0] reg_cha_len_msg_len;
  logic [15:0] w_cha_len_msg_len_nxt;
