  assign w_cha_irq_en_ctr_err_nxt = (w_we_cha_irq_en & (|w_wmask[4])) ? ((reg_wdata[4] & w_wmask[4]) | (reg_cha_irq_en_ctr_err & ~w_wmask[4])) : reg_cha_irq_en_ctr_err;

  // cha_irq_en_axi_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_en_axi_err_nxt = (w_we_cha_irq_en & (|w_wmask[3])) ? ((reg_wdata[3] & w_wmask[3]) | (reg_cha_irq_en_axi_err & ~w_wmask[3])) : reg_cha_irq_en_axi_err;

  // cha_irq_en_len_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_en_len_err_nxt = (w_we_cha_irq_en & (|w_wmask[2])) ? ((reg_wdata[2] & w_wmask[2]) | (reg_cha_irq_en_len_err & ~w_wmask[2])) : reg_cha_irq_en_len_err;

  // cha_irq_en_tag_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_en_tag_err_nxt = (w_we_cha_irq_en & (|w_wmask[1])) ? ((reg_wdata[1] & w_wmask[1]) | (reg_cha_irq_en_tag_err & ~w_wmask[1])) : reg_cha_irq_en_tag_err;

  // cha_irq_en_done next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_en_done_nxt = (w_we_cha_irq_en & (|w_wmask[0])) ? ((reg_wdata[0] & w_wmask[0]) | (reg_cha_irq_en_done & ~w_wmask[0])) : reg_cha_irq_en_done;

  // Register cha_irq_en: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_cha_irq_en
    if (!w_rst_n_reg) begin
      reg_cha_irq_en_key_err <= 1'h0;
      reg_cha_irq_en_ctr_err <= 1'h0;
      reg_cha_irq_en_axi_err <= 1'h0;
      reg_cha_irq_en_len_err <= 1'h0;
      reg_cha_irq_en_tag_err <= 1'h0;
      reg_cha_irq_en_done <= 1'h0;
    end else begin
      reg_cha_irq_en_key_err <= w_cha_irq_en_key_err_nxt;
      reg_cha_irq_en_ctr_err <= w_cha_irq_en_ctr_err_nxt;
      reg_cha_irq_en_axi_err <= w_cha_irq_en_axi_err_nxt;
      reg_cha_irq_en_len_err <= w_cha_irq_en_len_err_nxt;
      reg_cha_irq_en_tag_err <= w_cha_irq_en_tag_err_nxt;
      reg_cha_irq_en_done <= w_cha_irq_en_done_nxt;
    end
  end

  // Register cha_irq_en: output ports follow the flops.
  assign o_cha_irq_en_key_err = reg_cha_irq_en_key_err;
  assign o_cha_irq_en_ctr_err = reg_cha_irq_en_ctr_err;
  assign o_cha_irq_en_axi_err = reg_cha_irq_en_axi_err;
  assign o_cha_irq_en_len_err = reg_cha_irq_en_len_err;
  assign o_cha_irq_en_tag_err = reg_cha_irq_en_tag_err;
  assign o_cha_irq_en_done = reg_cha_irq_en_done;

  // Register cha_irq_en: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_cha_irq_en_value
    w_cha_irq_en_value = '0;
    w_cha_irq_en_value[5] = reg_cha_irq_en_key_err;
    w_cha_irq_en_value[4] = reg_cha_irq_en_ctr_err;
    w_cha_irq_en_value[3] = reg_cha_irq_en_axi_err;
    w_cha_irq_en_value[2] = reg_cha_irq_en_len_err;
    w_cha_irq_en_value[1] = reg_cha_irq_en_tag_err;
    w_cha_irq_en_value[0] = reg_cha_irq_en_done;
  end

  // cha_irq_inj_key_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_inj_key_err_nxt = (w_we_cha_irq_inj & (|w_wmask[5])) ? ((reg_wdata[5] & w_wmask[5]) | (reg_cha_irq_inj_key_err & ~w_wmask[5])) : reg_cha_irq_inj_key_err;

  // cha_irq_inj_ctr_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_inj_ctr_err_nxt = (w_we_cha_irq_inj & (|w_wmask[4])) ? ((reg_wdata[4] & w_wmask[4]) | (reg_cha_irq_inj_ctr_err & ~w_wmask[4])) : reg_cha_irq_inj_ctr_err;

  // cha_irq_inj_axi_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_inj_axi_err_nxt = (w_we_cha_irq_inj & (|w_wmask[3])) ? ((reg_wdata[3] & w_wmask[3]) | (reg_cha_irq_inj_axi_err & ~w_wmask[3])) : reg_cha_irq_inj_axi_err;

  // cha_irq_inj_len_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_inj_len_err_nxt = (w_we_cha_irq_inj & (|w_wmask[2])) ? ((reg_wdata[2] & w_wmask[2]) | (reg_cha_irq_inj_len_err & ~w_wmask[2])) : reg_cha_irq_inj_len_err;

  // cha_irq_inj_tag_err next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_inj_tag_err_nxt = (w_we_cha_irq_inj & (|w_wmask[1])) ? ((reg_wdata[1] & w_wmask[1]) | (reg_cha_irq_inj_tag_err & ~w_wmask[1])) : reg_cha_irq_inj_tag_err;

  // cha_irq_inj_done next value (rw): update only byte lanes selected by the bus strobe.
  assign w_cha_irq_inj_done_nxt = (w_we_cha_irq_inj & (|w_wmask[0])) ? ((reg_wdata[0] & w_wmask[0]) | (reg_cha_irq_inj_done & ~w_wmask[0])) : reg_cha_irq_inj_done;

  // Register cha_irq_inj: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_cha_irq_inj
    if (!w_rst_n_reg) begin
      reg_cha_irq_inj_key_err <= 1'h0;
      reg_cha_irq_inj_ctr_err <= 1'h0;
      reg_cha_irq_inj_axi_err <= 1'h0;
      reg_cha_irq_inj_len_err <= 1'h0;
      reg_cha_irq_inj_tag_err <= 1'h0;
      reg_cha_irq_inj_done <= 1'h0;
    end else begin
      reg_cha_irq_inj_key_err <= w_cha_irq_inj_key_err_nxt;
      reg_cha_irq_inj_ctr_err <= w_cha_irq_inj_ctr_err_nxt;
      reg_cha_irq_inj_axi_err <= w_cha_irq_inj_axi_err_nxt;
      reg_cha_irq_inj_len_err <= w_cha_irq_inj_len_err_nxt;
      reg_cha_irq_inj_tag_err <= w_cha_irq_inj_tag_err_nxt;
      reg_cha_irq_inj_done <= w_cha_irq_inj_done_nxt;
    end
  end

  // Register cha_irq_inj: output ports follow the flops.
  assign o_cha_irq_inj_key_err = reg_cha_irq_inj_key_err;
  assign o_cha_irq_inj_ctr_err = reg_cha_irq_inj_ctr_err;
  assign o_cha_irq_inj_axi_err = reg_cha_irq_inj_axi_err;
  assign o_cha_irq_inj_len_err = reg_cha_irq_inj_len_err;
  assign o_cha_irq_inj_tag_err = reg_cha_irq_inj_tag_err;
  assign o_cha_irq_inj_done = reg_cha_irq_inj_done;

  // Register cha_irq_inj: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_cha_irq_inj_value
    w_cha_irq_inj_value = '0;
    w_cha_irq_inj_value[5] = reg_cha_irq_inj_key_err;
    w_cha_irq_inj_value[4] = reg_cha_irq_inj_ctr_err;
    w_cha_irq_inj_value[3] = reg_cha_irq_inj_axi_err;
    w_cha_irq_inj_value[2] = reg_cha_irq_inj_len_err;
    w_cha_irq_inj_value[1] = reg_cha_irq_inj_tag_err;
    w_cha_irq_inj_value[0] = reg_cha_irq_inj_done;
  end

  // Register cha_irq_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_cha_irq_sts_value
    w_cha_irq_sts_value = '0;
    w_cha_irq_sts_value[5] = i_cha_irq_sts_key_err;
    w_cha_irq_sts_value[4] = i_cha_irq_sts_ctr_err;
    w_cha_irq_sts_value[3] = i_cha_irq_sts_axi_err;
    w_cha_irq_sts_value[2] = i_cha_irq_sts_len_err;
    w_cha_irq_sts_value[1] = i_cha_irq_sts_tag_err;
    w_cha_irq_sts_value[0] = i_cha_irq_sts_done;
  end

  // Register cha_cap: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_cha_cap_value
    w_cha_cap_value = '0;
    w_cha_cap_value[7:5] = i_cha_cap_core_log;
    w_cha_cap_value[4:3] = i_cha_cap_dw_code;
    w_cha_cap_value[2] = i_cha_cap_dma_en;
    w_cha_cap_value[1] = i_cha_cap_hold_en;
    w_cha_cap_value[0] = i_cha_cap_nonce_hw;
  end

  // Read data mux returns zero for addresses that do not map to a register.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (32'(reg_addr))
      LPARA_CHA_VERSION_OFFSET: w_rdata_nxt = w_cha_version_value;
      LPARA_CHA_CTRL_OFFSET: w_rdata_nxt = w_cha_ctrl_value;
      LPARA_CHA_LEN_OFFSET: w_rdata_nxt = w_cha_len_value;
      LPARA_CHA_WM_OFFSET: w_rdata_nxt = w_cha_wm_value;
      LPARA_CHA_NONCE0_OFFSET: w_rdata_nxt = w_cha_nonce0_value;
      LPARA_CHA_NONCE1_OFFSET: w_rdata_nxt = w_cha_nonce1_value;
      LPARA_CHA_NONCE2_OFFSET: w_rdata_nxt = w_cha_nonce2_value;
      LPARA_CHA_SALT_OFFSET: w_rdata_nxt = w_cha_salt_value;
      LPARA_CHA_CTR_LO_OFFSET: w_rdata_nxt = w_cha_ctr_lo_value;
      LPARA_CHA_CTR_HI_OFFSET: w_rdata_nxt = w_cha_ctr_hi_value;
      LPARA_CHA_STS_OFFSET: w_rdata_nxt = w_cha_sts_value;
      LPARA_CHA_IRQ_RAW_OFFSET: w_rdata_nxt = w_cha_irq_raw_value;
      LPARA_CHA_IRQ_EN_OFFSET: w_rdata_nxt = w_cha_irq_en_value;
      LPARA_CHA_IRQ_INJ_OFFSET: w_rdata_nxt = w_cha_irq_inj_value;
      LPARA_CHA_IRQ_STS_OFFSET: w_rdata_nxt = w_cha_irq_sts_value;
      LPARA_CHA_CAP_OFFSET: w_rdata_nxt = w_cha_cap_value;
      default: w_rdata_nxt = '0;
    endcase
  end

  // Read response storage follows the selected clock architecture.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_rdata
      logic [LPARA_DATA_W-1:0] reg_rdata_bus;

      // Snapshot read data in the register clock domain.
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
        if (!i_rst_n_reg)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end

      // The synchronized acknowledge qualifies the stable bundled read data.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
        if (!i_rst_n_apb)
          reg_rdata_bus <= '0;
        else if (w_rd_ack_fall)
          reg_rdata_bus <= reg_rdata;
      end
      assign o_apb_prdata = reg_rdata_bus;
    end else begin : g_sync_rdata
      // Synchronous read data is captured in the APB/register clock domain.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata
        if (!i_rst_n_apb)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end
      assign o_apb_prdata = reg_rdata;
    end
  endgenerate

endmodule
